package com.bank.totals;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class PayrollTotalsDemo {
    private static final Logger log = Logger.getLogger("Totals");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(1L, "Rajesh", new BigDecimal("95000.00")),
            new Employee(2L, "Priya", new BigDecimal("250000.00")),
            new Employee(3L, "Amit", new BigDecimal("120000.50")),
            new Employee(4L, "Sneha", new BigDecimal("180000.25"))
        );
        PayrollTotalsService service = new PayrollTotalsService();
        BigDecimal total = service.totalSalary(staff);
        log.info(() -> "Total monthly salary outflow = Rs. " + total);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final BigDecimal salary;
    Employee(Long id, String name, BigDecimal salary) { this.id = id; this.name = name; this.salary = salary; }
    String getName() { return name; }
    BigDecimal getSalary() { return salary; }
}

// ─── Would be in service/PayrollTotalsService.java ───
class PayrollTotalsService {
    // Three-arg reduce: identity ZERO, accumulator folds Employee→total, combiner merges partials.
    BigDecimal totalSalary(List<Employee> employees) {
        return employees.stream()
            .reduce(BigDecimal.ZERO,
                    (runningTotal, e) -> runningTotal.add(e.getSalary()),
                    BigDecimal::add);
    }
}
